const tabs = document.querySelectorAll('.d2t-tab');
const panes = document.querySelectorAll('.d2t--drawer');
const handleTabs = function(e){
    e.preventDefault();
    const ctx = this;
    if (ctx.classList.contains('is-active')) {
        const href = ctx.querySelector(`:scope ${"a"}`).getAttribute('href');
        const pane = document.querySelector(href);
        pane.classList.add('shown');
    } else {
        tabs.forEach((i) => i.classList.remove('is-active','d2t--selected'));
        ctx.classList.add('is-active','d2t--selected');
        const href = ctx.querySelector(`:scope ${"a"}`).getAttribute('href');
        panes.forEach((i) => {
            i.style.display = "none";
            i.classList.remove('shown');
        });
        const pane = document.querySelector(href);
        pane.style.display = "block";
        pane.classList.add('shown');
    }
};
tabs.forEach((item)=>{
    item.addEventListener('click', handleTabs);
});
const drawerHolder = document.querySelector("#drawers");
drawerHolder.addEventListener('click',function(evt){
    if (evt.target && evt.target.classList.contains('d2t--close')) {
        evt.target.parentNode.parentNode.classList.remove('shown');
    }
});
